head.b:skin:
:root{--cream:#F6F1E8;--ink:#20201E;--terra:#D85C4A;--sage:#A8B5A2;--blue:#8DA4B8;--yellow:#E4B85E;--white:#fff;--muted:#6f6b63;--line:#ded7ca}
*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.6}a{text-decoration:none;color:inherit}.wrap{width:min(1180px,92vw);margin:auto}
.top{border-bottom:1px solid var(--line);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);padding:10px 0}.brand{display:flex;justify-content:space-between;align-items:center;padding:25px 0}.logo{font-size:34px;font-weight:900;letter-spacing:-.06em;line-height:1}.sub{display:block;font-size:10px;letter-spacing:.2em;color:var(--muted);margin-top:8px}.search{padding:10px 15px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:12px;font-weight:800}
.nav{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:auto}.nav ul{list-style:none;display:flex;gap:22px;padding:14px 0;margin:0;white-space:nowrap}.nav a{font-size:12px;font-weight:800}.nav a:hover{color:var(--terra)}
.hero{display:grid;grid-template-columns:1.35fr .65fr;gap:22px;padding:32px 0}.hero-main{min-height:440px;border-radius:22px;background:url('https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&amp;fit=crop&amp;w=1500&amp;q=85') center/cover;position:relative;overflow:hidden}.hero-main:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 30%,rgba(0,0,0,.75))}.hero-text{position:absolute;left:0;right:0;bottom:0;z-index:2;color:#fff;padding:36px}.hero-text h1{font-size:clamp(42px,5vw,74px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.hero-text p{font-size:17px;margin:0;max-width:650px}.stack{display:grid;gap:22px}.card{background:#fff;border-radius:22px;padding:28px;min-height:209px;display:flex;flex-direction:column;justify-content:flex-end;box-shadow:0 18px 45px rgba(32,32,30,.08)}.tag{width:max-content;background:var(--sage);border-radius:999px;padding:6px 10px;font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}.card h2{font-size:26px;line-height:1.05;margin:10px 0}
.topics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:10px 0 35px}.topic{background:#fff;padding:24px;border-radius:18px;min-height:135px;display:flex;flex-direction:column;justify-content:space-between;box-shadow:0 12px 35px rgba(32,32,30,.06)}.topic span{font-size:10px;color:var(--muted);font-weight:900}.topic strong{font-size:18px}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:34px}.section-title{font-size:32px;letter-spacing:-.05em;margin:0 0 18px}.sidebar-box{background:#fff;padding:22px;border-radius:18px;margin-bottom:18px}.sidebar-box h3{font-size:13px;letter-spacing:.1em;text-transform:uppercase;margin-top:0}.sidebar-box ul{list-style:none;padding:0;margin:0}.sidebar-box li{padding:9px 0;border-bottom:1px solid var(--line)}
.footer{margin-top:55px;background:#191917;color:#eee;padding:55px 0}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:35px}.footer a{color:#bdb8ae}.copyright{border-top:1px solid #34342f;margin-top:30px;padding-top:18px;color:#8d8981;font-size:11px}
.Blog .blog-posts .post-outer{background:#fff;border-radius:22px;padding:32px;margin:0 0 22px;box-shadow:0 18px 45px rgba(32,32,30,.08)}.Blog .post-title{font-size:clamp(36px,5vw,60px)!important;line-height:1!important;letter-spacing:-.05em!important}.Blog .post-body{font-size:18px;line-height:1.8}.Blog .post-body img{border-radius:16px;max-width:100%;height:auto}.Blog .jump-link a{background:var(--terra);color:#fff!important;border-radius:999px;padding:10px 15px;font-size:11px;font-weight:900;text-transform:uppercase}
@media(max-width:900px){.hero{grid-template-columns:1fr}.topics{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.brand{padding:20px 0}.logo{font-size:29px}.search{display:none}.hero-main{min-height:370px}.hero-text{padding:24px}.hero-text h1{font-size:44px}.topics{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr}.Blog .blog-posts .post-outer{padding:22px}.Blog .post-title{font-size:38px!important}}
